    if(e.type==='finaleStart')announce('THE UNCROWNED · the final adversary',5);
    if(e.type==='finaleDown')announce('THE CROWN IS BROKEN',5);
    emotes?.feedback(e);art.feedback(e,reduced);if(e.type!=='chosen')sound(e.type,e);
    if(e.type==='majorCounter'||e.type==='majorStagger')announce(e.name+' · exposed. Make it count.',3);
    if(e.type==='relicTrial')announce('Last Chance Espresso: land three finishers!',3,3);
    if(e.type==='relicRevived')announce('A second chance. Make it count.');
    if(e.type==='relicRecipeReady')announce('A recipe rank is ready at the dealer.');
    if(e.type==='merchant')merchant();
    if(e.type==='grove')grove();
    if(e.type==='chapter')announce('Chapter '+e.chapter+' · '+e.name+' · '+e.hint,3);
    if(e.type==='endlessPhase'&&e.phase==='respite')announce('Lamps relit · collect the stars. Next wave in '+Math.ceil(game.state.endless.restRemaining)+'s.',3);
    if(e.type==='endlessPhase'&&e.phase==='gathering'&&game.state.time>10)announce(e.name+' · the next wave is here.',2);
    if(e.type==='endlessPhase'&&e.phase==='surge')announce(e.name+' · the chapter’s final surge.',2);
    if(e.type==='mastery'){const id={'Honed edge':'edge','Long-night supper':'vigor','Practised rhythm':'tempo'}[e.name];announce(e.name==='Night mastery'?'Night mastery · +250 score':(id?Food.get('training:'+id).name:e.name)+' mastered.',1);}
