    if(e.type==='finisher')finisherUntil=game.state.time+.65;
    if(e.type==='artChosen')announce(Engine.ARTS[e.id].name+' · a new way through the crowd.',2);
    if(e.type==='finisher'&&e.hits>0&&!reduced)impactPause=.026;
