      if(Math.abs(pad.axes[0])>.2)x=pad.axes[0];if(Math.abs(pad.axes[1])>.2)y=pad.axes[1];x+=(pad.buttons[15]?.pressed?1:0)-(pad.buttons[14]?.pressed?1:0);y+=(pad.buttons[13]?.pressed?1:0)-(pad.buttons[12]?.pressed?1:0);
