  function resumeDecisionMusic(){if(['merchant','grove'].includes(game?.state.status))unlockSound();if(!muted&&!document.hidden&&['upgrade','evolution'].includes(game?.state.status))music.play().catch(()=>{});}
  window.addEventListener('blur',loseFocus);window.addEventListener('focus',()=>{blurred=false;resumeDecisionMusic();});document.addEventListener('visibilitychange',()=>{if(document.hidden)loseFocus();else{blurred=false;resumeDecisionMusic();}});window.addEventListener('pagehide',()=>{music.dispose();audio?.close().catch(()=>{});});
  const pad=$('vs-stick');let pointer=null;const move=e=>{const r=pad.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,d=Math.hypot(dx,dy),scale=Math.min(1,35/Math.max(1,d));stick={x:dx*scale/35,y:dy*scale/35};pad.firstElementChild.style.transform=`translate(${dx*scale}px,${dy*scale}px)`;};
  pad.addEventListener('pointerdown',e=>{if(game?.state.status!=='playing'||pointer!==null)return;e.preventDefault();pointer=e.pointerId;pad.setPointerCapture(pointer);unlockSound();move(e);});pad.addEventListener('pointermove',e=>{if(e.pointerId===pointer)move(e);});const release=e=>{if(e.pointerId===pointer){pointer=null;stick={x:0,y:0};pad.firstElementChild.style.transform='';}};pad.addEventListener('pointerup',release);pad.addEventListener('pointercancel',release);pad.addEventListener('lostpointercapture',release);
  try{
    pack=window.MORATALES_SURVIVOR_PACK;if(!pack||!Engine||!Art)throw Error('Some game files could not be loaded.');model=createCharacterModel(pack);art=Art.create(canvas,model,pack);await art.ready;await window.ROUGE_MORA_FINALE_ART.ready;await window.MOROGUE_SITE_BRIDGE?.characters;const warnings=refreshProfiles();muted=typeof data.muted==='boolean'?data.muted:storage.getItem('moratales-menu-muted')==='true';reduced=typeof data.reducedMotion==='boolean'?data.reducedMotion:reduced;
    musicVolume=Number.isFinite(data.musicVolume)?Math.max(0,Math.min(1,data.musicVolume)):.25;effectsVolume=Number.isFinite(data.effectsVolume)?Math.max(0,Math.min(1,data.effectsVolume)):.6;music.volume=musicVolume;
    holdToAttack=data.holdToAttack===true;cameraFollow=data.cameraFollow!==false;cameraShake=['off','light','punchy'].includes(data.cameraShake)?data.cameraShake:'light';art.setCameraOptions({follow:cameraFollow,shake:cameraShake});
    emotes=window.ROUGE_MORA_EMOTES.create({canvas,getState:()=>game?.state,getReduced:()=>reduced,busy:()=>attackHeld||attackQueued||dashQueued||specialQueued||Math.hypot(stick.x,stick.y)>.12||[...held].some(k=>['w','a','s','d','arrowleft','arrowright','arrowup','arrowdown','j','shift',' '].includes(k))});
    window.addEventListener('resize',()=>art.resize());window.__moratalesSurvivor={get game(){return game;},get character(){return selected;},get data(){return data;},get emotes(){return emotes;},get camera(){return art.cameraState;},get sound(){return sfx;},get music(){return music;},get menuScene(){return menuScene.state;},get merchant(){return merchantScene?.debug;},get grove(){return groveScene?.debug;}};
    window.addEventListener('morogue-characters-changed',()=>{if(game)return;if(frontScreen==='setup'&&!dialog.open)lobby();else refreshProfiles();});
    if(data.loadout!=='solo')persist({loadout:'solo'});
    await window.SURVIVOR_FONT_READY;if(Engine.WEAPONS.some(w=>w.id===data.mainWeapon))weapon=data.mainWeapon;titleScreen();if(warnings.length)notice(warnings.join(' '));requestAnimationFrame(frame);
  }catch(e){$('vs-loading-message').textContent='The square could not open: '+e.message+' Refresh Morogue to try again.';console.error(e);}
